"""Docstring parsing and instruction injection for Integrum FastMCP tools."""

import docstring_parser
from typing import Dict, Optional


SERVER_INSTRUCTIONS = (
    "This MCP server is dynamically generated by Integrum.\n"
    "- State Management: Non-primitive Python objects (such as model instances, datasets, "
    "and arrays) are stored in memory and assigned memorable word IDs (e.g., 'playful_llama', 'swift_falcon').\n"
    "- Using Objects: When a tool returns an object ID, supply that ID to subsequent tools operating on it. "
    "For class methods, pass it as the 'obj_id' parameter. "
    "You can also use dot-notation for sub-attributes (e.g., 'swift_falcon.data' and 'swift_falcon.target')."
)


def format_function_description(
    raw_doc: Optional[str],
    is_constructor: bool = False,
    is_method: bool = False,
    class_name: Optional[str] = None,
    function_name: Optional[str] = None,
) -> str:
    """Format and enhance tool description with injected instructions."""
    summary_parts = []
    param_docs: Dict[str, str] = {}

    if raw_doc:
        try:
            parsed = docstring_parser.parse(raw_doc)
            if parsed.short_description:
                summary_parts.append(parsed.short_description)
            if parsed.long_description:
                # Add first 1-2 paragraphs of long description if reasonable
                long_desc = parsed.long_description.strip()
                if len(long_desc) > 500:
                    long_desc = long_desc[:500] + "..."
                summary_parts.append(long_desc)

            for param in parsed.params:
                if param.arg_name and param.description:
                    param_docs[param.arg_name] = param.description.strip()
        except Exception:
            summary_parts.append(raw_doc.strip()[:400])
    else:
        if is_constructor:
            summary_parts.append(f"Create an instance of {class_name}.")
        elif is_method:
            summary_parts.append(f"Execute method on {class_name} instance.")
        else:
            summary_parts.append("Execute Python function.")

    description_text = "\n\n".join(summary_parts)

    # Injected state management instructions
    injected_instructions = []
    if is_constructor:
        injected_instructions.append(
            "[STATE INSTRUCTION]: Calling this creates a new instance and returns an object ID "
            "(e.g. 'playful_llama'). Store this ID to pass as 'obj_id' in subsequent method calls."
        )
    elif is_method:
        injected_instructions.append(
            "[STATE INSTRUCTION]: Requires 'obj_id' referencing an existing instance. "
            "Arguments accepting datasets/arrays can accept registered object IDs or dot-notation "
            "(e.g. 'swift_falcon.data')."
        )
    elif function_name == "train_test_split":
        injected_instructions.append(
            "[STATE INSTRUCTION]: Pass arrays to split as a list, e.g. arrays=['<id>.data', '<id>.target'] "
            "(or arrays=['<id>_0', '<id>_1']), or X='...' and y='...'. "
            "Returns 4 arrays: X_train, X_test, y_train, y_test, which can be passed to subsequent tools."
        )
    elif function_name == "accuracy_score":
        injected_instructions.append(
            "[STATE INSTRUCTION]: Pass y_true and y_pred as object IDs (e.g. y_true='<split_id>.y_test', "
            "y_pred='<predictions_id>'). Returns accuracy float."
        )
    else:
        injected_instructions.append(
            "[STATE INSTRUCTION]: If this function returns a dataset or complex object, it will be "
            "registered in memory with a word ID. Arguments can also accept registered object IDs."
        )

    if injected_instructions:
        description_text += "\n\n" + "\n".join(injected_instructions)

    return description_text


def extract_parameter_descriptions(raw_doc: Optional[str]) -> Dict[str, str]:
    """Extract individual parameter descriptions from docstrings."""
    if not raw_doc:
        return {}
    param_docs = {}
    try:
        parsed = docstring_parser.parse(raw_doc)
        for param in parsed.params:
            if param.arg_name and param.description:
                param_docs[param.arg_name] = param.description.strip()
    except Exception:
        pass
    return param_docs
